const profiles = [];

function startSampler(getStack) {
  setInterval(() => {
    const stack = getStack();              // capture + symbolize inline
    profiles.push({ ts: Date.now(), stack });
  }, 1);                                    // sample every 1 ms
}

function flush() {
  send(profiles);                           // ship the whole buffer
}
// flush() is called from an admin endpoint, on demand
